{"command":"cd /workspace/fetched && python3 << 'EOF'
import csv, glob

# For each monthly file, check which stations have non-empty TOTAL_SNOW data
for fn in sorted(glob.glob("yow_20??-??.csv")):
    if "full_range" in fn: continue
    with open(fn) as fh:
        r = csv.DictReader(fh)
        station_snow = {}
        for row in r:
            cid = row["CLIMATE_IDENTIFIER"]
            name = row["STATION_NAME"]
            ts = row["TOTAL_SNOW"].strip()
            if ts and ts not in ("", "T", "M"):
                key = (cid, name)
                station_snow.setdefault(key, []).append((row["LOCAL_DATE"][:10], ts))
    # report stations with snow data
    if station_snow:
        print(f"\n{fn}: {len(station_snow)} stations with non-empty TOTAL_SNOW")
        for (cid, name), vals in sorted(station_snow.items()):
            nonzero = [(d,v) for d,v in vals if float(v)>0]
            print(f"  {name} ({cid}): {len(vals)} days w/ value, {len(nonzero)} nonzero, e.g. {nonzero[:3]}")
    else:
        # check if ANY field is populated for any station
        with open(fn) as fh:
            r = csv.DictReader(fh)
            anydata = False
            for row in r:
                if row["TOTAL_SNOW"].strip() or row["MAX_TEMPERATURE"].strip():
                    anydata = True; break
        print(f"{fn}: NO stations with TOTAL_SNOW data (any populated={anydata})")
EOF","description":"Check which Ottawa-region stations have actual snowfall data"}

